@Slf4j
@Component
@RequiredArgsConstructor
public class OrderCancellationListener {

    private final PaymentService paymentService;
    private final StripeService stripeService;

    @TransactionalEventListener
    public void onOrderCancelled(OrderCancelledEvent event) {
        var session_ids = paymentService.expirePendingPaymentsInNewTransaction(event.getOrderId());
        session_ids.forEach(stripeService::expireCheckoutSession);
        if (!session_ids.isEmpty()) {
            log.info("Expired {} pending checkout session(s) for cancelled order {}", session_ids.size(), event.getOrderId());
        }
    }
}
